function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';
  // Clock for time (1), Book for knowledge (2), Music note for harmony (3), Smiley for happiness (1)
  // Draw clock
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2, 30, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2);
  ctx.lineTo(W/2 - 100 + 20 * Math.sin(t), H/2 + 20 * Math.cos(t));
  ctx.stroke();

  // Draw book
  ctx.beginPath();
  ctx.rect(W/2 - 25, H/2 + 50, 50, 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 25, H/2 + 75);
  ctx.lineTo(W/2 + 25, H/2 + 75);
  ctx.stroke();

  // Draw music note
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 - 20);
  ctx.lineTo(W/2 + 70, H/2 - 20);
  ctx.stroke();

  // Draw smiley
  ctx.beginPath();
  ctx.arc(W/2 + 150, H/2, 30, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 150 - 15, H/2 - 15, 5, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 + 150 + 15, H/2 - 15, 5, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 + 150 - 20, H/2 + 10);
  ctx.quadraticCurveTo(W/2 + 150, H/2 + 30, W/2 + 150 + 20, H/2 + 10);
  ctx.stroke();
  ctx.restore();
}
